import{_ as t,a as s,b as o,c as n,d as a,e as g,f as i,g as e,h as l,i as p,j as h,k as u}from"./chunks/perspective.DPPPvFKX.js";import{_ as c,o as d,c as m,a2 as S}from"./chunks/framework.Bzj1XTnB.js";const B=JSON.parse('{"title":"ड्रॉइंग टूल और रंग","description":"ब्रश और अपना ब्रश बनाना, इरेज़र, फ़िल, टेक्स्ट, स्मज, ब्लर, मैजिक कट, आईड्रॉपर, रंग चुनने वाला और रूलर गाइड।","frontmatter":{"lang":"hi","slug":"drawing-tools","order":3,"title":"ड्रॉइंग टूल और रंग","description":"ब्रश और अपना ब्रश बनाना, इरेज़र, फ़िल, टेक्स्ट, स्मज, ब्लर, मैजिक कट, आईड्रॉपर, रंग चुनने वाला और रूलर गाइड।"},"headers":[],"relativePath":"hi/drawing-tools.md","filePath":"hi/drawing-tools.md"}'),_={name:"hi/drawing-tools.md"};function b(f,r,k,P,y,C){return d(),m("div",null,[...r[0]||(r[0]=[S('<h1 id="ड्रॉइंग-टूल-और-रंग" tabindex="-1">ड्रॉइंग टूल और रंग <a class="header-anchor" href="#ड्रॉइंग-टूल-और-रंग" aria-label="Permalink to &quot;ड्रॉइंग टूल और रंग&quot;">​</a></h1><h2 id="brush" tabindex="-1">Brush <a class="header-anchor" href="#brush" aria-label="Permalink to &quot;Brush&quot;">​</a></h2><p>टूलबार में <strong>Brush</strong> चुनें, फिर दाईं पट्टी पर <strong>Brush</strong> टैप करके छह समूहों के <strong>41 ब्रश</strong> में से चुनें: Basic (Pen, Pen Soft, Ink, Highlighter, Airbrush, Pixel…), Sketch (Pencil, Crayon, Calligraphy…), Texture (Spray, Grain, Halftone…), Effect (Gradient, 3D Brush, Candy Cane, Sparkles), Shape (Dots, Squares, Dash…) और Fun (Sprinkles, Leaves, Hair, Fur)। आपके ख़ुद बनाए ब्रश सबसे ऊपर <strong>My brushes</strong> में होते हैं।</p><p><img src="'+t+'" alt="ब्रश लाइब्रेरी"></p><p>आपका ब्रश, टूल के साइज़ और रंग वैसे ही रहते हैं जैसे आपने छोड़े थे, हर प्रोजेक्ट में, ऐप बंद करने के बाद भी।</p><p>ब्रश इस्तेमाल करने के लिए उस पर टैप करें, या उसकी सेटिंग बदलने के लिए बगल के <strong>›</strong> पर:</p><p><img src="'+s+'" alt="ब्रश सेटिंग"></p><ul><li><strong>Stabilizer</strong> — काँपती लकीरों को चिकना करता है। ज़्यादा करने पर लकीर और चिकनी होती है, पर उँगली के पीछे धीरे चलती है।</li><li><strong>Thickness</strong> — 1 से 200 पिक्सेल।</li><li><strong>Opacity</strong> — लकीर कितनी पारदर्शी हो।</li><li><strong>Color</strong> — और दो रंग वाले ब्रश (Gradient, Candy Cane, Sparkles, Sprinkles, Static) के लिए <strong>Second color</strong> भी।</li><li><strong>Pressure &amp; advanced</strong> — स्टाइलस से दबाव के हिसाब से साइज़ और/या पारदर्शिता बदल सकती है।</li></ul><p><strong>टिप:</strong> रूलर चालू या बंद करने के लिए Brush टूल पर डबल-टैप करें।</p><h3 id="अपना-ब्रश-बनाएँ" tabindex="-1">अपना ब्रश बनाएँ <a class="header-anchor" href="#अपना-ब्रश-बनाएँ" aria-label="Permalink to &quot;अपना ब्रश बनाएँ&quot;">​</a></h3><p>ब्रश मेकर खोलने के लिए <strong>My brushes</strong> के नीचे <strong>New brush</strong> टैप करें। ब्रश आज़माने के लिए ऊपर के काग़ज़ पर कुछ बनाइए: नीचे की हर सेटिंग बदलते ही वह आपकी अपनी लकीर पर फिर से बन जाती है। ब्रश रखने के लिए <strong>✓</strong> टैप करें; वह <strong>My brushes</strong> में भी आ जाता है और आपके हाथ में भी। अपने किसी ब्रश के बगल का <strong>›</strong> उसे बदलने के लिए फिर से खोलता है।</p><p><img src="'+o+'" alt="ब्रश मेकर"></p><ul><li><strong>Name</strong> — सूची में ब्रश का नाम।</li><li><strong>Start from</strong> — शुरुआत के लिए तैयार लुक: Ink pen, Sketch pencil, Chisel marker, Soft airbrush, Dry brush, Chalk, Splatter, Stars, Twinkles, Hearts, Leaves, Bubbles और Confetti।</li><li><strong>Tip</strong> — वह आकार जिसे ब्रश लकीर पर छापता है: Round, Soft, Pencil, Chalk, Square, Bristle, Splatter, Star, Sparkle, Heart, Leaf, Ring — या <strong>Picture</strong>, आपकी गैलरी की कोई भी तस्वीर। हल्के काग़ज़ पर गहरा आकार, या पारदर्शी बैकग्राउंड वाली PNG सबसे अच्छी चलती है; गहरी तस्वीर पर हल्के आकार के लिए <strong>Paint with the light parts</strong> चालू करें। <ul><li><strong>Roundness</strong> टिप को चपटी निब बना देता है, <strong>Angle</strong> उसे घुमाता है, और <strong>Turn with the stroke</strong> से टिप आपकी लकीर की दिशा में मुड़ती है (पत्तों, ब्रिसल और कैलीग्राफ़ी के लिए अच्छा)।</li></ul></li><li><strong>Stroke</strong> — <strong>Brush size</strong> और <strong>Color</strong> (वही जो ब्रश सेटिंग में है), <strong>Spacing</strong> (छापों के बीच की दूरी), <strong>Flow</strong> (हर छाप कितनी गहरी हो: 100% से कम पर एक-दूसरे पर पड़ते ही गहरी होती हैं) और <strong>Stamps per step</strong>।</li><li><strong>Taper</strong> — लकीर अपनी <strong>Start</strong> और <strong>End</strong> पर कितनी पतली हो, और साथ में फीकी भी हो या नहीं। अंत उँगली उठाते ही पतला होता है, जब लकीर की लंबाई पता चल जाती है।</li><li><strong>Randomness</strong> — हर छाप थोड़ी अलग: <strong>Size</strong>, <strong>Opacity</strong>, <strong>Angle</strong>, <strong>Scatter</strong> (लकीर से दूर), <strong>Hue</strong> और <strong>Brightness</strong>।</li><li><strong>Texture</strong> — काग़ज़ का दाना जिससे लकीर दबकर निकलती है (Pencil, Crayon, Canvas, Grunge, Dots, Hatch), उसकी <strong>Depth</strong> और <strong>Scale</strong> के साथ। दाना काग़ज़ पर टिका रहता है, असली पेंसिल की तरह।</li><li>अपना बनाया ब्रश बदलते समय नीचे <strong>Save as a copy</strong> और <strong>Delete brush</strong> मिलते हैं।</li></ul><p>आपके ब्रश ऐप के साथ रखे जाते हैं, इसलिए हर प्रोजेक्ट उन्हें इस्तेमाल कर सकता है। साइज़, opacity, रंग और smoothing पहले की तरह ब्रश सेटिंग से आते हैं, बिल्ट-इन ब्रश की तरह।</p><h2 id="eraser" tabindex="-1">Eraser <a class="header-anchor" href="#eraser" aria-label="Permalink to &quot;Eraser&quot;">​</a></h2><p><img src="'+n+'" alt="साइज़ के गोले के साथ इरेज़र"></p><p>इरेज़र सिर्फ़ मौजूदा लेयर से ड्रॉइंग मिटाता है।</p><ul><li><strong>Size</strong> — 1 से 200 पिक्सेल। मिटाते समय <strong>इरेज़र के साइज़ का एक गोला</strong> आपकी उँगली के साथ चलता है, ताकि साफ़ दिखे कि क्या मिटेगा। (यह गोला <strong>Settings → Drawing → Eraser outline</strong> में बंद कर सकते हैं।)</li><li><strong>Fade</strong> — इरेज़र का किनारा मुलायम करता है, ताकि ड्रॉइंग किनारे पर धीरे-धीरे मिटे, एकदम कटे नहीं।</li><li><strong>Opacity</strong> — कम करने पर थोड़ा-थोड़ा मिटता है।</li></ul><h2 id="fill" tabindex="-1">Fill <a class="header-anchor" href="#fill" aria-label="Permalink to &quot;Fill&quot;">​</a></h2><p>किसी बंद आकार के अंदर टैप करें — उसमें रंग भर जाता है।</p><p><img src="'+a+'" alt="फ़िल टूल"></p><ul><li><strong>Threshold</strong> — टैप की गई जगह से कितना अलग रंग भी भर जाए। किनारों के पास जगह छूट जाए तो इसे बढ़ाएँ।</li><li><strong>Sample all layers</strong> (फ़िल सेटिंग में) — हर दिखने वाली लेयर की लकीरें सीमा का काम करती हैं, पर रंग मौजूदा लेयर पर भरता है। अलग लाइन-आर्ट लेयर के नीचे रंग भरने के लिए एकदम सही।</li></ul><h2 id="text" tabindex="-1">Text <a class="header-anchor" href="#text" aria-label="Permalink to &quot;Text&quot;">​</a></h2><p><strong>Text</strong> चुनें (न दिखे तो <strong>⋯</strong> में), फिर जहाँ टेक्स्ट चाहिए वहाँ टैप करें। दाईं पट्टी से पहले ही <strong>Color</strong>, <strong>Size</strong> और <strong>Font</strong> चुन सकते हैं।</p><p><img src="'+g+'" alt="टेक्स्ट टूल"></p><p><img src="'+i+'" alt="टेक्स्ट जोड़ें"></p><p>अपने शब्द लिखें, <strong>Font</strong> (Sans, Serif, Mono, Cursive, Condensed, Poppins), <strong>Size</strong>, <strong>Bold</strong>/<strong>Italic</strong>, अलाइनमेंट और <strong>Color</strong> चुनें, फिर <strong>Add</strong> पर टैप करें। टेक्स्ट चुने हुए रूप में आता है — रखने से पहले उसे हिला, बड़ा-छोटा और घुमा सकते हैं।</p><h2 id="smudge-blur-magic-cut-और-eyedropper" tabindex="-1">Smudge, Blur, Magic cut और Eyedropper <a class="header-anchor" href="#smudge-blur-magic-cut-और-eyedropper" aria-label="Permalink to &quot;Smudge, Blur, Magic cut और Eyedropper&quot;">​</a></h2><p>चारों टूलबार के <strong>⋯</strong> कार्ड में हैं।</p><ul><li><strong>Smudge</strong> — गीले रंग में उँगली की तरह रंगों को धकेलता और मिलाता है। <strong>Strength</strong> बताता है रंग कितनी दूर जाए।</li><li><strong>Blur</strong> — आपकी लकीर के नीचे की लकीरों को मुलायम करता है।</li><li><strong>Magic cut</strong> — ड्रॉइंग के आसपास के बैकग्राउंड पर टैप करें, ड्रॉइंग एक बार में उठ जाती है — हिलाने, बड़ा-छोटा करने या ऑब्जेक्ट के रूप में सेव करने के लिए तैयार। ड्रॉइंग के अंदर टैप करें तो सिर्फ़ वही आकार कटता है।</li><li><strong>Eyedropper</strong> — कहीं भी टैप करें, वह रंग चुन लिया जाता है। फिर आप सीधे पिछले टूल पर लौट आते हैं।</li></ul><h2 id="रंग-चुनने-वाला-कलर-पिकर" tabindex="-1">रंग चुनने वाला (कलर पिकर) <a class="header-anchor" href="#रंग-चुनने-वाला-कलर-पिकर" aria-label="Permalink to &quot;रंग चुनने वाला (कलर पिकर)&quot;">​</a></h2><p>दाईं पट्टी पर <strong>Color</strong> टैप करें।</p><p><img src="'+e+'" alt="रंग का पहिया"></p><ul><li><strong>ऊपर की पट्टी:</strong> आईड्रॉपर (अपनी ड्रॉइंग से रंग चुनें), <strong>+</strong> (यह रंग अपने पैलेट में जोड़ें), और पुराना व नया रंग — पुराने पर टैप करें तो वही वापस आ जाता है।</li><li><strong>नीचे के टैब:</strong><ul><li><strong>Wheel</strong> — रंग का घेरा, बीच में चमक/गहराई, किनारे की चाप पर पारदर्शिता। बारीकी के लिए बीच में पिंच या डबल-टैप करके ज़ूम करें।</li><li><strong>Classic</strong> — एक चौकोर और स्लाइडर।</li><li><strong>Harmony</strong> — साथ में अच्छे लगने वाले रंग (complementary, triadic और भी)।</li><li><strong>Value</strong> — सटीक HEX, HSV या RGB नंबर लिखें।</li><li><strong>Swatch</strong> — हाल के रंग और पैलेट।</li></ul></li></ul><p><img src="'+l+'" alt="पैलेट"></p><p>Toonik में पहले से पैलेट हैं (Basic, Sketch, Retro Animation, Neon और भी)। अपना पैलेट बनाने के लिए <strong>New palette</strong> टैप करें (हर पैलेट में 12 रंग तक)। <strong>किसी रंग पर लॉन्ग-प्रेस करके उसे बदलें</strong>, और पैलेट का नाम बदलने, कॉपी करने या हटाने के लिए उसे स्वाइप करें।</p><h2 id="रूलर-और-गाइड" tabindex="-1">रूलर और गाइड <a class="header-anchor" href="#रूलर-और-गाइड" aria-label="Permalink to &quot;रूलर और गाइड&quot;">​</a></h2><p>पट्टी पर <strong>Ruler</strong> टैप करें (या Brush पर डबल-टैप)। नीचे एक पट्टी आती है।</p><p><img src="'+p+'" alt="रूलर पट्टी"></p><ul><li><strong>Line</strong>, <strong>Circ</strong> (गोला/अंडाकार) और <strong>Box</strong> — एकदम सही आकार के साथ-साथ ड्रॉ करें। गाइड को उसके गुलाबी हैंडल से हिलाएँ और बड़ा-छोटा करें। हटाने के लिए चालू आकार पर फिर टैप करें।</li><li><strong>Mirr</strong> — आईना: एक तरफ़ जो बनाएँ, दूसरी तरफ़ भी बनता है।</li><li><strong>Pers</strong> — 1, 2 या 3 वैनिशिंग पॉइंट वाली पर्सपेक्टिव गाइड (<strong>1PT / 2PT / 3PT</strong>)। गाइड लाइन के पास से शुरू हुई लकीर उसी पर चलती है। <strong>Grid</strong> से लाइनें कम-ज़्यादा करें। गुलाबी पॉइंट खींचकर उसे हिलाएँ। जो पॉइंट स्क्रीन से बाहर या नीचे की पट्टियों के पीछे हो, वह किनारे पर एक छोटे तीर के साथ दिखता है जो उसकी ओर इशारा करता है: उसे खींचें तो पॉइंट आपकी उँगली के साथ चलता है।</li><li><strong>Lock</strong> — गाइड गलती से हिलने से रोकता है।</li><li><strong>✕</strong> — रूलर बंद करता है।</li></ul><p><img src="'+h+'" alt="गोला और आईना गाइड"></p><p><img src="'+u+'" alt="पर्सपेक्टिव गाइड"></p>',42)])])}const q=c(_,[["render",b]]);export{B as __pageData,q as default};
